# A fresh EOS comparison trains two KD pilots from 03 and measures their shared
# starting student. A full experiment also needs a trained SFT control.
control_result = None
historical_evidence = {"status": "fresh_comparison", "starting_point": "verified_03"}
if MODE == "train":
    if HISTORICAL_RUN_DIRECTORY is not None and RUN_STAGE in {"eos_comparison", "full"}:
        historical_evidence = verify_historical_run(
            HISTORICAL_RUN_DIRECTORY, checkpoint_hashes, protocol, splits, config
        )
        control_result = historical_evidence["control"]
        control_checkpoint_directory = Path(historical_evidence["control_checkpoint"])
        print("Historical SFT control from:", historical_evidence["directory"])
    elif RUN_STAGE != "eos_comparison":
        # Build this control only when continuing to a full experiment or using
        # the standalone pilot workflow. It uses the same fixed training recipe.
        control_result = train_arm("sft_control")
        control_checkpoint_directory = run_directory / "checkpoints/sft_control"
    else:
        print("Fresh comparison: both EOS pilots start from the verified 03 checkpoint.")
    write_json(run_directory / "historical_evidence.json", historical_evidence)
    if control_result is not None:
        display(pd.DataFrame([control_result["final_validation"]]))
else:
    print("INSPECT: comparison orchestration defined; GPU arms remain pending.")

if MODE == "train" and FULL_RUN_COMPLETE:
    # Score unchanged validation prefixes for the control and final KD checkpoint
    # while the teacher is still available. These are not optimizer inputs.
    fixed_diagnostics = {"starting_sft": starting_fixed_diagnostics}
    for arm in ("sft_control", "on_policy"):
        checkpoint_directory = (
            control_checkpoint_directory
            if arm == "sft_control"
            else run_directory / "checkpoints" / arm
        )
        evaluated_student = load_student(checkpoint_directory, device)
        fixed_diagnostics[arm] = fixed_trajectory_diagnostics(
            evaluated_student, teacher, diagnostic_trajectories, device, compute_dtype, config
        )
        del evaluated_student
        release_cuda_memory()
    write_json(run_directory / "fixed_diagnostics.json", fixed_diagnostics)
    display(
        pd.DataFrame(
            [
                {"checkpoint": arm, "fixed_prefix_forward_kl_nats": result["mean_forward_kl_nats"]}
                for arm, result in fixed_diagnostics.items()
            ]
        )
    )
    del teacher
    release_cuda_memory()
    print("Teacher released before the final generated-answer evaluations.")
else:
    print("PENDING: no real fixed-prefix model comparison available yet.")

# Every arm receives the exact same held-out questions and decoding rules.
# The teacher is already released; no reference answer is passed to generate().
if MODE == "train" and FULL_RUN_COMPLETE:
    primary_evaluations, historical_evaluations = {}, {}
    checkpoint_directories = {
        "starting_sft": starting_checkpoint_directory,
        "sft_control": control_checkpoint_directory,
        "on_policy": run_directory / "checkpoints/on_policy",
    }
    for arm, checkpoint_directory in checkpoint_directories.items():
        evaluated_student = load_student(checkpoint_directory, device)
        primary_evaluations[arm] = evaluate_and_save(
            evaluated_student, splits["primary_test"], f"{arm}_primary_test"
        )
        historical_evaluations[arm] = evaluate_and_save(
            evaluated_student, splits["historical_test"], f"{arm}_historical_test"
        )
        del evaluated_student
        release_cuda_memory()
    primary_summary = pd.DataFrame(
        [
            evaluation_summary(result, arm, "primary_test")
            for arm, result in primary_evaluations.items()
        ]
    )
    display(primary_summary)
    print("Previously inspected subset, shown separately:")
    display(
        pd.DataFrame(
            [
                evaluation_summary(result, arm, "historical_test")
                for arm, result in historical_evaluations.items()
            ]
        )
    )
    paired_comparisons = {
        f"{first}_to_{second}": paired_accuracy_difference(
            primary_evaluations[first], primary_evaluations[second]
        )
        for first, second in [
            ("starting_sft", "sft_control"),
            ("starting_sft", "on_policy"),
            ("sft_control", "on_policy"),
        ]
    }
    display(pd.DataFrame(paired_comparisons).T)
    write_json(run_directory / "paired_comparisons.json", paired_comparisons)
    plot_run(
        {"sft_control": control_result["history"], "on_policy": on_policy_result["history"]},
        primary_evaluations,
        run_directory,
    )
    from IPython.display import Image

    display(Image(filename=str(run_directory / "training_objectives.png")))
    display(Image(filename=str(run_directory / "primary_test_comparison.png")))
else:
    print("PENDING: final exam generation and performance figures await train mode.")

if MODE == "train" and FULL_RUN_COMPLETE:
    before = primary_evaluations["starting_sft"]
    after = primary_evaluations["on_policy"]
    before_rows = {r["example_id"]: r for r in before["rows"]}
    after_rows = {r["example_id"]: r for r in after["rows"]}
    before_scores = {r["example_id"]: r for r in before["annotations"]}
    changed_answers = []
    for row in after["annotations"]:
        key = row["example_id"]
        if before_scores[key]["strict_correct"] != row["strict_correct"]:
            changed_answers.append(
                {
                    "example_id": key,
                    "change": "improved" if row["strict_correct"] else "regressed",
                    "question": before_rows[key]["question"],
                    "expected_answer": before_rows[key]["expected_answer"],
                    "starting_response": before_rows[key]["response_text"],
                    "on_policy_response": after_rows[key]["response_text"],
                }
            )
    # Include both directions in the visible preview instead of cherry-picking gains.
    preview = [
        r
        for direction in ("improved", "regressed")
        for r in [v for v in changed_answers if v["change"] == direction][:2]
    ]
    display(pd.DataFrame(preview))
    write_json(run_directory / "changed_answers.json", changed_answers)
else:
    print("PENDING: no generated-answer changes to inspect.")
